        \  let drop_columns = fun (t:[?], cs:[String]) ->\n\
        \    map(t,fun row -> to_lvs(row) |> filter(_, fun entry -> !any(cs, \
         string_eq(entry.label, _))) |> from_lvs):[?] in\n\
        \  \n\
